queries.q_Q1006.rq:
SELECT DISTINCT ?item ?lang ?name ?kind WHERE {
  ?item wdt:P17 wd:Q1006 .
  FILTER EXISTS { ?item skos:altLabel ?alias . FILTER(LANG(?alias) IN ("en","fr")) }
  FILTER NOT EXISTS { ?item wdt:P31 wd:Q5 }
  { ?item rdfs:label ?name . BIND("label" AS ?kind) }
  UNION { ?item skos:altLabel ?name . BIND("alias" AS ?kind) }
  BIND(LANG(?name) AS ?lang)
  FILTER(?lang IN ("en","fr","wo","tw","ak","ee","bm","ff"))
}

